from collections import Counter

class Solution:
    def quotaWindow(self, text: str, quota: str) -> str:
        if not quota:
            return ""
        need = Counter(quota)
        missing, left = len(quota), 0
        best_start, best_length = 0, len(text) + 1
        for right, char in enumerate(text):
            if char in need:
                if need[char] > 0:
                    missing -= 1
                need[char] -= 1
            while missing == 0:
                length = right - left + 1
                if length < best_length:
                    best_start, best_length = left, length
                char = text[left]
                if char in need:
                    need[char] += 1
                    if need[char] > 0:
                        missing += 1
                left += 1
        return "" if best_length > len(text) else text[best_start:best_start + best_length]
